    'legal.termsBody':
      'หน้านี้เป็นฉบับตัวอย่างของข้อตกลงการใช้งาน HaoFang.World ฝ่ายกฎหมายกำลังจัดทำข้อความทางการและจะนำมาแทนที่หน้านี้\n\nจนกว่าฉบับทางการจะมีผล การใช้งานแพลตฟอร์มถือว่าคุณรับทราบว่าแพลตฟอร์มให้บริการเพียงการแสดงข้อมูลประกาศและการจับคู่เท่านั้น ไม่ถือเป็นการค้ำประกันการทำธุรกรรมใด ๆ ข้อมูลประกาศมาจากผู้เผยแพร่ โปรดตรวจสอบด้วยตนเองก่อนชมและลงนาม\n\nหากมีข้อสงสัยเกี่ยวกับข้อตกลง โปรดติดต่อเราผ่าน «โปรไฟล์ - ติดต่อฝ่ายบริการ»',
    'legal.privacyBody':
      'หน้านี้เป็นฉบับตัวอย่างของนโยบายความเป็นส่วนตัว HaoFang.World ฝ่ายกฎหมายกำลังจัดทำข้อความทางการและจะนำมาแทนที่หน้านี้\n\nเราเก็บรวบรวมข้อมูลเท่าที่จำเป็นสำหรับการค้นหาที่พัก การนัดชม และการสื่อสารผ่านข้อความ รวมถึงชื่อ เบอร์โทรศัพท์ และประวัติการเรียกดูที่คุณให้ไว้ เราจะไม่ใช้ข้อมูลเหล่านี้เพื่อวัตถุประสงค์ที่ไม่เกี่ยวข้องกับบริการโดยไม่ได้รับความยินยอมจากคุณ\n\nคุณสามารถขอเข้าถึง แก้ไข หรือลบข้อมูลส่วนบุคคลได้ทุกเมื่อผ่าน «โปรไฟล์ - ติดต่อฝ่ายบริการ»',
